SELECT CASE WHEN s.risk_reward_ratio < 1 THEN 'RR<1' ELSE 'RR>=1' END AS rr_bucket, p.status, COUNT(*) AS n, SUM(CASE WHEN p.realized_pnl > 0 THEN 1 ELSE 0 END) AS winners, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, ROUND(AVG(s.atr_percent), 4) AS avg_atr_pct FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id WHERE p.closed_at IS NOT NULL GROUP BY rr_bucket, p.status ORDER BY rr_bucket, p.status